package ray2sing

import (
	"os"
	"strings"
	"testing"

	T "github.com/sagernet/sing-box/option"
)

// TestPanelLinks parses the exact links generated by MasterDNS Panel
// (path in env PANEL_LINKS) the same way Hiddify core does, and checks the
// resulting masterdns outbound struct carries the right domain, key,
// encryption and resolvers — including a custom ISP resolver.
func TestPanelLinks(t *testing.T) {
	data, err := os.ReadFile(os.Getenv("PANEL_LINKS"))
	if err != nil {
		t.Skip("PANEL_LINKS not set")
	}
	lines := strings.Split(strings.TrimSpace(string(data)), "\n")
	key := strings.TrimPrefix(lines[3], "KEY=")
	for i, link := range lines[:3] {
		if strings.HasPrefix(link, "dnst://") {
			link = expandDnstLink(link)
			if !strings.HasPrefix(link, "masterdns://") {
				t.Fatalf("link %d: dnst expansion gave %q", i+1, link)
			}
		}
		ob, err := MasterdnsSingbox(link)
		if err != nil {
			t.Fatalf("link %d parse error: %v", i+1, err)
		}
		opts, ok := ob.Options.(*T.MasterDNSOptions)
		if !ok {
			t.Fatalf("link %d: options type %T, not *MasterDNSOptions", i+1, ob.Options)
		}
		t.Logf("link %d -> domains=%v resolvers=%v encryption=%q key=%q smart_pool=%v",
			i+1, []string(opts.Domains), []string(opts.Resolvers), opts.Encryption, opts.Key, opts.SmartPool != nil)
		if got := []string(opts.Domains); len(got) != 1 || got[0] != "test-user.example.com" {
			t.Errorf("link %d: domains = %v", i+1, got)
		}
		if opts.Key != key {
			t.Errorf("link %d: key = %q, want %q", i+1, opts.Key, key)
		}
		if opts.Encryption != "aes-256-gcm" && opts.Encryption != "5" {
			t.Errorf("link %d: encryption = %q (want aes-256-gcm or its id 5)", i+1, opts.Encryption)
		}
		resolvers := []string(opts.Resolvers)
		for _, want := range []string{"8.8.8.8", "1.1.1.1", "10.150.2.73"} {
			found := false
			for _, r := range resolvers {
				if r == want {
					found = true
				}
			}
			if !found {
				t.Errorf("link %d: resolvers %v missing %q", i+1, resolvers, want)
			}
		}
	}
}
